[package]
name = "meilisearch"
publish = false

version.workspace = true
authors.workspace = true
description.workspace = true
homepage.workspace = true
readme.workspace = true
edition.workspace = true
license.workspace = true

default-run = "meilisearch"

[dependencies]
actix-cors = "0.7.1"
actix-http = { version = "3.13.3", default-features = false, features = [
    "compress-brotli",
    "compress-gzip",
    "rustls-0_23",
] }
actix-web = { version = "4.14.1", default-features = false, features = [
    "macros",
    "compress-brotli",
    "compress-gzip",
    "cookies",
    "rustls-0_23",
] }
anyhow = { version = "1.0.104", features = ["backtrace"] }
bstr = "1.13.1"
byte-unit = { version = "5.2.5", features = ["serde"] }
bytes = "1.12.1"
bumpalo = "3.20.3"
clap = { version = "4.6.6", features = ["derive", "env"] }
crossbeam-channel = "0.5.16"
deserr = { version = "0.6.4", features = ["actix-web"] }
dump = { path = "../dump" }
either = "1.17.0"
file-store = { path = "../file-store" }
flate2 = "1.1.9"
futures = { version = "0.3.34", default-features = false, features = ["std", "async-await"] }
futures-util = "0.3.34"
index-scheduler = { path = "../index-scheduler" }
http-client = { path = "../http-client" }
indexmap = { version = "2.14.0", features = ["serde"] }
is-terminal = "0.4.17"
itertools = "0.14.0"
jsonwebtoken = { version = "10.4.0", default-features = false, features = ["rust_crypto", "hmac", "sha2", "rand"] }
lazy_static = "1.5.0"
liquid = "0.26.11"
meilisearch-auth = { path = "../meilisearch-auth" }
meilisearch-types = { path = "../meilisearch-types" }
memmap2 = "0.9.11"
mime = "0.3.17"
num_cpus = "1.17.0"
obkv = "0.3.0"
permissive-json-pointer = { path = "../permissive-json-pointer" }
pin-project-lite = "0.2.17"
platform-dirs = "0.3.0"
prometheus = { version = "0.14.0", default-features = false, features = ["process"] }
rand = "0.10.2"

regex = "1.13.1"
rustls = { version = "0.23.43", features = ["ring"], default-features = false }

rustls-pemfile = "2.2.0"
segment = { version = "0.2.6" }
serde = { version = "1.0.229", features = ["derive"] }
serde_json = { version = "1.0.151", features = ["preserve_order"] }
static-files = { version = "0.3.1", optional = true }
sysinfo = { version = "0.38.4", default-features = false, features = ["system", "disk"] }
tempfile = "3.27.0"
thiserror = "2.0.20"
time = { version = "0.3.55", features = [
    "serde-well-known",
    "formatting",
    "parsing",
    "macros",
] }
tokio = { version = "1.53.1", features = ["full"] }
toml = { version = "1.1.4", default-features = false, features = ["std", "serde", "parse"] }
uuid = { version = "1.24.0", features = ["serde", "v4", "v7"] }
serde_urlencoded = "0.7.1"
termcolor = "1.4.1"
url = { version = "2.5.8", features = ["serde"] }
tracing = "0.1.44"
tracing-subscriber = { version = "0.3.23", features = ["json"] }
tracing-trace = { version = "0.1.0", path = "../tracing-trace" }
tracing-actix-web = "0.7.22"
build-info = { version = "1.7.0", path = "../build-info" }
roaring = "0.11.5"
mopa-maintained = "0.2.3"
utoipa = { version = "5.5.0", features = [
    "actix_extras",
    "macros",
    "non_strict_integers",
    "preserve_order",
    "uuid",
    "time",
    "openapi_extensions",
] }
utoipa-scalar = { version = "0.3.0", optional = true, features = ["actix-web"] }
async-openai = { path = "../../external-crates/async-openai" }
secrecy = "0.10.3"
actix-web-lab = { version = "0.26.0", default-features = false }
urlencoding = "2.1.3"
backoff = { version = "0.4.0", features = ["tokio"] }
humantime = { version = "2.4.0", default-features = false }
cidr = { version = "0.3.2", features = ["serde"] }
routes = { path = "../routes" }
bumparaw-collections = "0.2.0"
fst = "0.4.7"

[target.'cfg(not(windows))'.dependencies]
tikv-jemallocator = { workspace = true }

[dev-dependencies]
actix-rt = "2.11.0"
brotli = "8.0.4"
# fixed version due to format breakages in v1.40
insta = { version = "=1.39.0", features = ["redactions"] }
manifest-dir-macros = "0.1.20"
maplit = "1.0.2"
meili-snap = { path = "../meili-snap" }
temp-env = "0.3.6"
wiremock = "0.6.5"
yaup = "0.3.1"

[build-dependencies]
anyhow = { version = "1.0.104", optional = true }
cargo_toml = { version = "0.22.3", optional = true }
hex = { version = "0.4.3", optional = true }
reqwest = { version = "0.12.28", features = [
    "blocking",
    "rustls-tls",
], default-features = false, optional = true }
sha-1 = { version = "0.10.1", optional = true }
static-files = { version = "0.3.1", optional = true }
tempfile = { version = "3.27.0", optional = true }
zip = { version = "6.0.0", optional = true, default-features = false, features = ["deflate-flate2"] }

[features]
default = ["meilisearch-types/all-tokenizations", "mini-dashboard"]
swagger = ["utoipa-scalar"]
test-ollama = []
mini-dashboard = [
    "static-files",
    "anyhow",
    "cargo_toml",
    "hex",
    "reqwest",
    "sha-1",
    "tempfile",
    "zip",
]
chinese = ["meilisearch-types/chinese"]
chinese-pinyin = ["meilisearch-types/chinese-pinyin"]
enterprise = ["meilisearch-types/enterprise", "index-scheduler/enterprise"]
hebrew = ["meilisearch-types/hebrew"]
japanese = ["meilisearch-types/japanese"]
korean = ["meilisearch-types/korean"]
thai = ["meilisearch-types/thai"]
greek = ["meilisearch-types/greek"]
khmer = ["meilisearch-types/khmer"]
vietnamese = ["meilisearch-types/vietnamese"]
swedish-recomposition = ["meilisearch-types/swedish-recomposition"]
german = ["meilisearch-types/german"]
turkish = ["meilisearch-types/turkish"]

[package.metadata.mini-dashboard]
assets-url = "https://github.com/meilisearch/mini-dashboard/releases/download/v0.4.2/build.zip"
sha1 = "6a8a76d9ed79357959bc6d4e3816f753a605a27b"
